fn conditional_average(vals_1: &Vec<u64>, vals_2: &Vec<u64>, conds_1: &Vec<bool>, conds_2: &Vec<bool>, avgs: &mut Vec<u64>) {
    // Clear the output vector to ensure it's empty before filling
    avgs.clear();
    
    // Iterate through all indices (assuming all vectors have the same length)
    for i in 0..vals_1.len() {
        let c1 = conds_1[i];
        let c2 = conds_2[i];
        
        // According to the problem, at least one boolean is always true
        let result = match (c1, c2) {
            (true, true) => {
                // Integer average: (a + b) / 2
                (vals_1[i] + vals_2[i]) / 2
            }
            (true, false) => {
                // Only first boolean is true
                vals_1[i]
            }
            (false, true) => {
                // Only second boolean is true
                vals_2[i]
            }
            // The case (false, false) should never happen based on the problem statement
            (false, false) => {
                // This is a defensive fallback - could also panic or use default
                // Using 0 as fallback since it's a valid u64
                0
            }
        };
        
        avgs.push(result);
    }
}